-- Additive policy storage; historical requests and assessments are retained.
CREATE TABLE IF NOT EXISTS company_leave_policies (employer_id UUID NOT NULL REFERENCES employer_accounts(id),leave_year INTEGER NOT NULL CHECK(leave_year BETWEEN 1900 AND 2200),policy JSONB NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(employer_id,leave_year));
CREATE TABLE IF NOT EXISTS employee_leave_entitlements (employer_id UUID NOT NULL REFERENCES employer_accounts(id),employee_id UUID NOT NULL REFERENCES workforce_employees(id),leave_year INTEGER NOT NULL CHECK(leave_year BETWEEN 1900 AND 2200),category TEXT NOT NULL CHECK(category IN ('annual','sick','maternity','paternity','compassionate','study','unpaid','other')),allowance NUMERIC(8,2) NOT NULL CHECK(allowance BETWEEN 0 AND 366),opening_days NUMERIC(8,2) NOT NULL DEFAULT 0 CHECK(opening_days BETWEEN 0 AND 366),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(employer_id,employee_id,leave_year,category));
ALTER TABLE ats_jobs ADD COLUMN IF NOT EXISTS qualifying_score INTEGER NOT NULL DEFAULT 85 CHECK(qualifying_score BETWEEN 0 AND 100);
-- Null policy identifies historical applications and preserves their existing workflow.
ALTER TABLE ats_applications ADD COLUMN IF NOT EXISTS assessment_policy JSONB;
CREATE TABLE IF NOT EXISTS applicant_career_profiles (applicant_id UUID PRIMARY KEY REFERENCES applicant_accounts(id),skills TEXT NOT NULL DEFAULT '',experience TEXT NOT NULL DEFAULT '',education TEXT NOT NULL DEFAULT '',cv_filename TEXT,cv_content BYTEA CHECK(octet_length(cv_content)<=2097152),cv_updated_at TIMESTAMPTZ,general_questions JSONB,general_answers JSONB,general_score INTEGER CHECK(general_score BETWEEN 0 AND 100),general_completed_at TIMESTAMPTZ,reviewed_at TIMESTAMPTZ,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
